  -- 01. Montelukast y otros controladores: eficacia comparada y seguridad neuropsiquiátrica
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Las pesadillas del montelukast","texto":"Un niño de ocho años empieza montelukast y a las semanas tiene pesadillas e irritabilidad. La familia no relaciona los síntomas con el medicamento. El INVIMA ya emitió una alerta: preguntar, vigilar y reportar es parte de la dispensación segura."},"objetivos":["Aplicar la indicación del montelukast.","Comparar su eficacia con la del ICS.","Reconocer la alerta neuropsiquiátrica.","Revisar interacciones y alternativas."],"conceptos":[{"icono":"Pill","termino":"Montelukast","definicion":"Antagonista del receptor de leucotrienos."},{"icono":"ShieldCheck","termino":"Añadido","definicion":"Complemento, no reemplazo del ICS."},{"icono":"AlertTriangle","termino":"Neuropsiquiátrico","definicion":"Pesadillas, ansiedad, depresión e ideas suicidas."},{"icono":"FileCheck","termino":"Reporte","definicion":"Notificación al Programa Nacional de Farmacovigilancia."}],"secciones":[{"titulo":"Indicación y eficacia","parrafos":["El montelukast bloquea el receptor de leucotrienos. La presentación de 10 mg está indicada, a partir de los 15 años, como tratamiento añadido en asma persistente leve a moderada no controlada con ICS y SABA a demanda, y para prevenir la broncoconstricción por ejercicio. También puede aliviar la rinitis alérgica estacional en esos pacientes. La dosis es 10 mg una vez al día por la noche.","GINA 2026 considera los antileucotrienos menos eficaces que el ICS. En niños de 6-11 años son una alternativa en el paso 2, con la advertencia neuropsiquiátrica. No sirven para crisis agudas y no deben reemplazar de forma brusca a los corticoides."]},{"titulo":"Seguridad neuropsiquiátrica","parrafos":["Se han reportado alteraciones del sueño, pesadillas, ansiedad, depresión, agresividad e ideación suicida en todas las edades. El INVIMA, en su Informe de seguridad 349-2024, pidió informar el riesgo, preguntar por antecedentes de depresión o ideación suicida antes de iniciar, suspender ante síntomas nuevos y reportar al Programa Nacional de Farmacovigilancia.","En la dispensación se pregunta por antecedentes psiquiátricos y se advierte a la familia qué observar. Los síntomas suelen mejorar al suspender, pero la decisión debe ser médica y documentada."]},{"titulo":"Otros controladores e interacciones","parrafos":["La teofilina y el salbutamol orales no se recomiendan en asma por su perfil de eficacia y seguridad. En EPOC, el roflumilast y la azitromicina son opciones de seguimiento en perfiles seleccionados. Los biológicos se reservan para asma grave con fenotipo definido.","El fenobarbital reduce la exposición al montelukast cerca de 40 % y los inductores del CYP3A4 pueden disminuir su efecto. El gemfibrozilo la aumenta unas 4,4 veces sin requerir ajuste. El QF revisa estas interacciones y documenta."]}],"errores":[{"error":"Usarlo como reemplazo del ICS.","correccion":"Es menos eficaz."},{"error":"No preguntar por antecedentes psiquiátricos.","correccion":"La alerta lo exige."},{"error":"No reportar la sospecha.","correccion":"La farmacovigilancia protege a otros."}],"comprueba":[{"pregunta":"¿Dosis en adultos?","respuesta":"10 mg una vez al día por la noche."},{"pregunta":"¿Sirve en crisis?","respuesta":"No."},{"pregunta":"¿Qué alerta emitió el INVIMA?","respuesta":"Reacciones neuropsiquiátricas en todas las edades."}],"resumen":["El montelukast es un añadido, no la base.","Es menos eficaz que el ICS.","La alerta neuropsiquiátrica obliga a vigilar.","La sospecha se reporta al INVIMA."],"referencias":[{"cita":"INVIMA. Informe de seguridad No. 349-2024: riesgo de reacciones neuropsiquiátricas asociadas al tratamiento con montelukast. Bogotá; 2024.","url":"https://www.invima.gov.co/alertas-sanitarias/riesgo-de-reacciones-neuropsiquiatricas-asociadas-al-tratamiento-con-montelukast"},{"cita":"AEMPS-CIMA. Ficha técnica de Singulair 10 mg comprimidos recubiertos con película. Revisión octubre 2025.","url":"https://cima.aemps.es/cima/dochtml/ft/61980/FT_61980.html"}],"imagenes":[{"ubicacion":"Controladores","descripcion":"Caja de montelukast con advertencia de sueño y ánimo.","alt":"Montelukast y seguridad neuropsiquiátrica"}],"keywords":["montelukast","antileucotrienos asma","invima montelukast","pesadillas montelukast"],"mapa":{"centro":"Montelukast","ramas":[{"titulo":"Indicación","icono":"Target","nodos":["Asma leve-moderada","Ejercicio","Rinitis"]},{"titulo":"Dosis","icono":"Pill","nodos":["10 mg","Nocturna","Adultos"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Sueño","Ánimo","Suicidio"]},{"titulo":"Interacción","icono":"Network","nodos":["Fenobarbital","Rifampicina","Gemfibrozilo"]}]},"proceso":{"titulo":"Checklist del montelukast","intro":"","pasos":[{"titulo":"Indicación","detalle":"Añadido o ejercicio.","icono":"Target","evidencia":"Diagnóstico."},{"titulo":"Antecedentes","detalle":"Depresión o ideación.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Advertencia","detalle":"Sueño y ánimo.","icono":"AlertTriangle","evidencia":"Consejería."},{"titulo":"Interacción","detalle":"Inductores e inhibidores.","icono":"Network","evidencia":"Lista."},{"titulo":"Reporte","detalle":"Sospecha al INVIMA.","icono":"FileCheck","evidencia":"Reporte."}]},"caso":{"titulo":"Niño con pesadillas","contexto":"Niño de 8 años en Neiva con asma que inicia montelukast 5 mg y presenta pesadillas e irritabilidad.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Decir que es normal y continuar.","correcta":false,"retro":"Es una reacción descrita y debe evaluarse."},{"texto":"Orientar consulta, reportar al INVIMA y reforzar el ICS.","correcta":true,"retro":"La seguridad y el control del asma son prioritarios."},{"texto":"Suspender el ICS.","correcta":false,"retro":"El ICS es la base del tratamiento."}]}}$j$::jsonb;
