  -- 02. Caso: paciente con asma que solo usa salbutamol y presenta sobreuso
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cuatro inhaladores en seis meses","texto":"Laura usa salbutamol casi a diario, se despierta dos noches por semana y compra sus inhaladores sin fórmula. Su asma no está controlada y el patrón de dispensación lo demuestra. La intervención del QF empieza por contar, preguntar y educar."},"objetivos":["Cuantificar el sobreuso de SABA.","Evaluar el control del asma.","Aplicar una intervención educativa.","Documentar la remisión al médico."],"conceptos":[{"icono":"Calculator","termino":"Sobreuso","definicion":"Tres o más inhaladores al año ya es riesgo."},{"icono":"ClipboardList","termino":"Control","definicion":"Síntomas diurnos, despertares y limitación."},{"icono":"GraduationCap","termino":"Técnica","definicion":"Errores críticos anulan el efecto."},{"icono":"FileCheck","termino":"Remisión","definicion":"Comunicación documentada al médico."}],"secciones":[{"titulo":"Cuantificar y evaluar","parrafos":["Primero se cuantifica el uso: inhaladores dispensados en 12 meses y disparos por semana. Después se evalúa el control con preguntas de GINA o el ACT: síntomas diurnos, despertares nocturnos, limitación de actividad y uso de rescate. También se buscan exacerbaciones y ciclos de corticoide oral.","Se revisan técnica, desencadenantes y comorbilidades como rinitis. En el caso, Laura usa cuatro inhaladores de 200 dosis en seis meses, un ritmo de ocho al año, se despierta dos noches por semana y recibió prednisolona hace tres meses."]},{"titulo":"Riesgos del sobreuso","parrafos":["GINA 2026 señala que usar tres o más inhaladores de SABA al año se asocia con exacerbaciones más graves y doce o más con muerte por asma. El SABA regular aumenta la inflamación y reduce su propio efecto. El estudio SABINA III mostró que 38 % de los pacientes recibían más de tres inhaladores al año y 20 % los compraban sin fórmula.","El paciente suele interpretar el alivio como control. Explicar la diferencia entre aliviar y controlar es una intervención educativa central."]},{"titulo":"Intervención","parrafos":["El QF corrige la técnica, propone una cámara espaciadora si hay problemas de coordinación, revisa la rinitis y comunica al médico los hallazgos con una propuesta basada en GINA: tratamiento con ICS, idealmente en la vía 1 con ICS-formoterol como rescate. La remisión se documenta.","Se acuerda un plan de acción escrito y un seguimiento en cuatro semanas con conteo de rescate, ACT y técnica. La educación se hace sin alarmar y reconociendo que el paciente buscaba alivio."]}],"errores":[{"error":"No contar los inhaladores.","correccion":"Es el dato más objetivo."},{"error":"No revisar la técnica.","correccion":"Puede explicar el mal control."},{"error":"No tratar la rinitis.","correccion":"Contribuye al control del asma."}],"comprueba":[{"pregunta":"¿Cuántos SABA al año son riesgo?","respuesta":"Tres o más."},{"pregunta":"¿Qué es el ACT?","respuesta":"Test de control del asma."},{"pregunta":"¿Qué tratamiento debe incluir?","respuesta":"Un corticoide inhalado."}],"resumen":["El sobreuso de SABA es un indicador de riesgo.","Hay que evaluar control, técnica y comorbilidades.","La educación diferencia alivio de control.","La remisión documentada cierra el ciclo."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Bhattarai A, Shakya R, Bista D. Impact of pharmacist-led intervention on adherence to inhalers, inhalation technique, and disease control among asthma/COPD patients. Patient Prefer Adherence. 2024;18:1395-408.","url":"https://doi.org/10.2147/ppa.s460810"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Registro de inhaladores dispensados y síntomas de la paciente.","alt":"Caso de sobreuso de salbutamol"}],"keywords":["sobreuso salbutamol","saba asma","caso asma","act","sabina iii"],"mapa":{"centro":"Sobreuso de SABA","ramas":[{"titulo":"Datos","icono":"Calculator","nodos":["Inhaladores/año","Disparos/semana","Compras"]},{"titulo":"Control","icono":"ClipboardList","nodos":["Nocturno","Diurno","Actividad"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Exacerbación","Muerte","Inflamación"]},{"titulo":"Intervención","icono":"Users","nodos":["Educar","Técnica","Remitir"]}]},"proceso":{"titulo":"Intervención en sobreuso","intro":"","pasos":[{"titulo":"Contar","detalle":"Inhaladores y dosis.","icono":"Calculator","evidencia":"Historial."},{"titulo":"Evaluar","detalle":"Control y exacerbaciones.","icono":"ClipboardList","evidencia":"ACT."},{"titulo":"Revisar","detalle":"Técnica y comorbilidades.","icono":"Eye","evidencia":"Observación."},{"titulo":"Educar","detalle":"Aliviar no es controlar.","icono":"GraduationCap","evidencia":"Consejería."},{"titulo":"Remitir","detalle":"Propuesta documentada.","icono":"FileCheck","evidencia":"Nota."}]},"caso":{"titulo":"Laura en Cali","contexto":"Mujer de 28 años con asma, cuatro inhaladores de salbutamol en seis meses, síntomas nocturnos dos veces por semana y rinitis sin tratar.","pregunta":"¿Cuál es la prioridad?","opciones":[{"texto":"Venderle más salbutamol.","correcta":false,"retro":"Perpetúa el sobreuso."},{"texto":"Educar, corregir técnica y remitir para ICS.","correcta":true,"retro":"Aborda la causa del sobreuso."},{"texto":"Suspender el salbutamol sin más.","correcta":false,"retro":"Necesita un plan de reemplazo."}]}}$j$::jsonb;
