  -- 03. Introducción a la unidad: metas y ciclo de manejo del asma según GINA 2026
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Controlar hoy y proteger mañana","texto":"El asma se trata con dos metas: que el paciente viva sin síntomas y que no tenga crisis ni pierda función pulmonar. GINA propone un ciclo de evaluar, ajustar y revisar. Sin ese ciclo, el tratamiento se vuelve una receta repetida."},"objetivos":["Resumir las metas del tratamiento.","Aplicar el ciclo evaluar-ajustar-revisar.","Reconocer los mensajes clave de GINA 2026.","Entender las dos vías de tratamiento."],"conceptos":[{"icono":"Target","termino":"Control","definicion":"Síntomas mínimos y vida normal."},{"icono":"ShieldCheck","termino":"Riesgo futuro","definicion":"Exacerbaciones, pérdida de función y muerte."},{"icono":"Repeat","termino":"Ciclo","definicion":"Evaluar, ajustar y revisar."},{"icono":"Route","termino":"Dos vías","definicion":"Vía 1 con ICS-formoterol y vía 2 alternativa."}],"secciones":[{"titulo":"Las metas","parrafos":["El tratamiento busca controlar los síntomas para que el paciente lleve una vida normal y reducir el riesgo futuro de exacerbaciones, deterioro de la función pulmonar, efectos adversos y muerte. Las dos metas se evalúan en cada visita y no siempre coinciden: un paciente puede sentirse bien y tener riesgo alto.","GINA propone un ciclo continuo: evaluar diagnóstico, control, factores de riesgo, técnica, adherencia y preferencias; ajustar medicamentos y estrategias no farmacológicas; y revisar respuesta, satisfacción y efectos adversos."]},{"titulo":"Mensajes clave de GINA 2026","parrafos":["Evitar el tratamiento solo con SABA; todo paciente debe recibir tratamiento con corticoide inhalado; revisar la técnica en cada visita; entregar un plan de acción escrito, digital o con imágenes; y, tras 2-3 meses de buen control, considerar reducir el tratamiento sin suspender del todo el ICS en adultos y adolescentes.","Después de una sola exacerbación que requiera urgencias o corticoide oral, se debe revisar el tratamiento para prevenir nuevas crisis. La exacerbación es una señal de riesgo, no un evento aislado."]},{"titulo":"Las dos vías","parrafos":["En adultos y adolescentes, la vía 1, preferida, usa ICS-formoterol como rescate; la vía 2, alternativa, usa ICS-SABA o SABA como rescate. La vía 1 simplifica el esquema y asegura que cada rescate aporte corticoide. En ambas, el paso 5 incluye remisión a valoración experta y biológicos.","Para el QF, conocer la vía del paciente permite revisar coherencia, técnica y adherencia. También permite detectar esquemas inseguros, como SABA solo o LABA sin ICS."]}],"errores":[{"error":"Evaluar solo los síntomas.","correccion":"El riesgo futuro también cuenta."},{"error":"Mantener SABA solo.","correccion":"Todo asma requiere ICS."},{"error":"No revisar la técnica.","correccion":"Es parte del ciclo."}],"comprueba":[{"pregunta":"¿Cuáles son las dos metas?","respuesta":"Control de síntomas y reducción del riesgo."},{"pregunta":"¿Qué vía es la preferida?","respuesta":"La vía 1 con ICS-formoterol."},{"pregunta":"¿Se puede suspender el ICS?","respuesta":"No del todo en adultos y adolescentes."}],"resumen":["El manejo tiene dos metas inseparables.","El ciclo se repite en cada visita.","Todo asma requiere ICS.","El plan escrito y la técnica son claves."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Unidad 3","descripcion":"Ciclo evaluar-ajustar-revisar aplicado al asma.","alt":"Metas y ciclo de manejo del asma GINA 2026"}],"keywords":["manejo asma","gina 2026 metas","ciclo asma","vía 1 vía 2"],"mapa":{"centro":"Manejo del asma","ramas":[{"titulo":"Metas","icono":"Target","nodos":["Síntomas","Crisis","Función"]},{"titulo":"Ciclo","icono":"Repeat","nodos":["Evaluar","Ajustar","Revisar"]},{"titulo":"Claves","icono":"Lightbulb","nodos":["Sin SABA solo","ICS siempre","Plan escrito"]},{"titulo":"Vías","icono":"Route","nodos":["Vía 1","Vía 2","Paso 5"]}]},"proceso":{"titulo":"Ciclo de manejo","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Control, riesgo y técnica.","icono":"Search","evidencia":"Ficha."},{"titulo":"Ajustar","detalle":"Medicamentos y educación.","icono":"Settings","evidencia":"Plan."},{"titulo":"Revisar","detalle":"Respuesta y adherencia.","icono":"Eye","evidencia":"Control."},{"titulo":"Escalar","detalle":"Si no hay control.","icono":"LineChart","evidencia":"Paso."},{"titulo":"Reducir","detalle":"Con buen control.","icono":"Repeat","evidencia":"Ajuste."}]},"caso":{"titulo":"Paciente estable con SABA","contexto":"Paciente que se siente bien pero usa salbutamol tres veces por semana y no tiene ICS.","pregunta":"¿Qué conclusión es correcta?","opciones":[{"texto":"Está controlado y no requiere cambios.","correcta":false,"retro":"El rescate frecuente indica riesgo."},{"texto":"No está controlado y debe recibir ICS.","correcta":true,"retro":"GINA exige tratamiento con ICS."},{"texto":"Debe suspender el rescate.","correcta":false,"retro":"Necesita un plan de reemplazo."}]}}$j$::jsonb;
