  -- 04. Vías 1 y 2 de GINA 2026 en adultos y adolescentes: pasos 1 a 5
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Un solo inhalador en todos los pasos","texto":"La vía 1 de GINA usa ICS-formoterol como rescate en todos los pasos. Eso significa que cada alivio también trata la inflamación. La vía 2 mantiene el rescate con SABA o ICS-SABA. Conocer la diferencia evita esquemas incoherentes."},"objetivos":["Diferenciar las vías 1 y 2.","Aplicar los pasos 1 a 5 en adultos.","Revisar la coherencia del esquema.","Reconocer el límite del inserto colombiano."],"conceptos":[{"icono":"Route","termino":"Vía 1","definicion":"ICS-formoterol como rescate en todos los pasos."},{"icono":"Repeat","termino":"Vía 2","definicion":"ICS-SABA o SABA como rescate."},{"icono":"Layers","termino":"MART","definicion":"Mantenimiento y rescate con el mismo inhalador."},{"icono":"FileText","termino":"Inserto","definicion":"En Colombia prevalece la indicación aprobada."}],"secciones":[{"titulo":"Vía 1","parrafos":["En los pasos 1-2 se usa rescate antiinflamatorio con ICS-formoterol a dosis baja a necesidad. En el paso 3, MART con ICS-formoterol a dosis baja: una inhalación mañana y noche más una a necesidad. En el paso 4, MART a dosis media: dos inhalaciones mañana y noche más una a necesidad. En el paso 5 se remite para valoración experta.","La ventaja es usar un solo inhalador en todos los pasos y que cada rescate aporte corticoide. La desventaja es que exige educación clara para que el paciente no confunda mantenimiento con rescate."]},{"titulo":"Vía 2","parrafos":["En el paso 1 se usa AIR con ICS-SABA a dosis baja; si solo hay SABA, se toma una dosis baja de ICS cada vez que se usa el SABA. En el paso 2, ICS a dosis baja de mantenimiento. En el paso 3, ICS-LABA a dosis baja. En el paso 4, ICS-LABA a dosis media. En el paso 5 se remite, igual que en la vía 1.","Antes de subir un paso se revisan técnica, adherencia, exposición y comorbilidades. Muchos fracasos aparentes se corrigen sin cambiar el medicamento."]},{"titulo":"El inserto colombiano","parrafos":["La ficha técnica de referencia de budesonida-formoterol 160/4,5 indica el producto en asma desde los 12 años, en mantenimiento o como MART, y dice que no se recomienda en el tratamiento inicial del asma. GINA, en cambio, propone AIR desde el paso 1.","En Colombia prevalece el inserto aprobado por el INVIMA, por lo que el uso como AIR debe verificarse frente a la indicación aprobada. El QF revisa la edad, la indicación y la dosis del producto que dispensa, y consulta al prescriptor si hay discrepancia."]}],"errores":[{"error":"Mezclar vías sin criterio.","correccion":"El esquema debe ser coherente."},{"error":"Subir de paso sin revisar técnica.","correccion":"Se sobretrata un problema corregible."},{"error":"Ignorar el inserto INVIMA.","correccion":"La indicación aprobada prevalece."}],"comprueba":[{"pregunta":"¿Qué distingue la vía 1?","respuesta":"ICS-formoterol como rescate."},{"pregunta":"¿Qué es MART?","respuesta":"Mantenimiento y rescate con el mismo inhalador."},{"pregunta":"¿Qué se revisa antes de escalar?","respuesta":"Técnica, adherencia, exposición y comorbilidad."}],"resumen":["GINA 2026 tiene dos vías.","La vía 1 usa ICS-formoterol como rescate.","La vía 2 usa ICS-SABA o SABA.","Antes de escalar se corrigen factores modificables."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación. Revisión febrero 2021.","url":"https://cima.aemps.es/cima/dochtml/ft/63958/FT_63958.html"}],"imagenes":[{"ubicacion":"Vías","descripcion":"Diagrama de pasos 1 a 5 en las dos vías de GINA.","alt":"Vías 1 y 2 de GINA 2026"}],"keywords":["gina pasos asma","vía 1 gina","vía 2 gina","air mart","budesonida formoterol"],"mapa":{"centro":"Pasos GINA","ramas":[{"titulo":"Vía 1","icono":"Route","nodos":["AIR","MART","Dosis media"]},{"titulo":"Vía 2","icono":"Repeat","nodos":["ICS-SABA","ICS diario","ICS-LABA"]},{"titulo":"Paso 5","icono":"Target","nodos":["LAMA","Dosis alta","Biológicos"]},{"titulo":"Revisión","icono":"Eye","nodos":["Técnica","Adherencia","Comorbilidad"]}]},"proceso":{"titulo":"Verificación del paso","intro":"","pasos":[{"titulo":"Identificar","detalle":"Vía y paso actual.","icono":"Route","evidencia":"Fórmula."},{"titulo":"Revisar","detalle":"Técnica y adherencia.","icono":"Eye","evidencia":"Entrevista."},{"titulo":"Comprobar","detalle":"Dosis y dispositivo.","icono":"ClipboardCheck","evidencia":"Esquema."},{"titulo":"Ajustar","detalle":"Subir o bajar con criterio.","icono":"Settings","evidencia":"Nota."},{"titulo":"Remitir","detalle":"Paso 5 a especialista.","icono":"FileCheck","evidencia":"Remisión."}]},"caso":{"titulo":"MART con dosis baja sin control","contexto":"Paciente en paso 3 con MART a dosis baja que sigue con síntomas diurnos.","pregunta":"¿Qué se revisa antes de subir?","opciones":[{"texto":"Solo aumentar la dosis.","correcta":false,"retro":"Primero se corrigen técnica y adherencia."},{"texto":"Técnica, adherencia, exposición y comorbilidades.","correcta":true,"retro":"Son causas frecuentes de mal control."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"Empeoraría."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Vías 1 y 2 de GINA 2026 en adultos y adolescentes: pasos 1 a 5$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
