  -- 05. MART con budesonida-formoterol: dosificación, límites y educación
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Doce inhalaciones en un día","texto":"Un paciente con MART usa el mismo inhalador para mantenimiento y rescate, pero no sabe cuántas inhalaciones son el límite. La educación sobre dosis máxima y signos de alarma evita retrasos peligrosos en la atención."},"objetivos":["Aplicar la dosificación de MART.","Reconocer los límites diarios.","Educar sobre técnica y enjuague.","Detectar cuándo consultar."],"conceptos":[{"icono":"Layers","termino":"MART","definicion":"Mantenimiento y rescate con ICS-formoterol."},{"icono":"Pill","termino":"Dosis","definicion":"Una inhalación mañana y noche más rescate."},{"icono":"Calculator","termino":"Límite","definicion":"Normalmente no más de 8 al día."},{"icono":"GraduationCap","termino":"Educación","definicion":"Diferenciar mantenimiento y rescate."}],"secciones":[{"titulo":"Dosificación","parrafos":["En el esquema MART, el paciente usa budesonida-formoterol para mantenimiento y para rescate. En el paso 3, una inhalación mañana y noche más una a necesidad; si los síntomas persisten, puede repetir una inhalación. En el paso 4, dos inhalaciones mañana y noche más una a necesidad.","No se deben superar seis inhalaciones en una sola ocasión. Normalmente no se usan más de ocho al día, aunque por un tiempo limitado se puede llegar a doce. Si se necesitan más de doce en 24 horas, el paciente debe consultar."]},{"titulo":"Técnica y seguridad","parrafos":["El dispositivo de polvo seco exige inhalar fuerte y profundo y nunca exhalar dentro de la boquilla. Después de las dosis de mantenimiento se enjuaga la boca para reducir candidiasis y disfonía. La dosis liberada de 160/4,5 equivale a la dosis medida de 200/6.","El paciente debe saber que el mismo inhalador cumple dos funciones y que el mantenimiento no se omite aunque se sienta bien. La confusión entre mantenimiento y rescate es el error más frecuente."]},{"titulo":"Límites y consulta","parrafos":["El aumento del uso de rescate indica pérdida de control. El QF pregunta cuántas inhalaciones usa al día, revisa la fecha de vencimiento y el contador del dispositivo, y refuerza el plan de acción. Si el paciente necesita más de doce al día o no mejora, debe buscar atención urgente.","MART reduce exacerbaciones frente a ICS-LABA fijo con SABA, pero solo funciona con educación y adherencia. El seguimiento debe incluir técnica, uso de rescate y efectos adversos."]}],"errores":[{"error":"No explicar los dos usos.","correccion":"Es la base del MART."},{"error":"No fijar límites.","correccion":"El paciente no sabe cuándo consultar."},{"error":"No revisar técnica.","correccion":"El polvo seco exige inhalar fuerte."}],"comprueba":[{"pregunta":"¿Dosis de mantenimiento en paso 3?","respuesta":"Una inhalación mañana y noche."},{"pregunta":"¿Máximo por ocasión?","respuesta":"Seis inhalaciones."},{"pregunta":"¿Cuándo consultar?","respuesta":"Más de doce en 24 horas o sin mejoría."}],"resumen":["MART usa un inhalador para dos funciones.","El mantenimiento no se omite.","Hay límites por ocasión y por día.","La educación y el seguimiento son esenciales."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"AEMPS-CIMA. Ficha técnica de Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación. Revisión febrero 2021.","url":"https://cima.aemps.es/cima/dochtml/ft/63958/FT_63958.html"}],"imagenes":[{"ubicacion":"MART","descripcion":"Esquema gráfico de mantenimiento y rescate con límites.","alt":"MART con budesonida-formoterol"}],"keywords":["mart asma","budesonida formoterol dosis","mantenimiento y rescate","límite inhalaciones"],"mapa":{"centro":"MART","ramas":[{"titulo":"Mantenimiento","icono":"CalendarClock","nodos":["Mañana","Noche","Todos los días"]},{"titulo":"Rescate","icono":"Zap","nodos":["1 inhalación","Otra si persiste","Máximo por ocasión"]},{"titulo":"Límites","icono":"Calculator","nodos":["8 al día","Hasta 12 temporal","Consultar"]},{"titulo":"Técnica","icono":"Eye","nodos":["Inhalar fuerte","No soplar","Enjuagar"]}]},"proceso":{"titulo":"Educación MART","intro":"","pasos":[{"titulo":"Explicar","detalle":"Dos funciones del inhalador.","icono":"BookOpen","evidencia":"Consejería."},{"titulo":"Demostrar","detalle":"Inhalación y enjuague.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Fijar","detalle":"Dosis de mantenimiento.","icono":"CalendarClock","evidencia":"Horario."},{"titulo":"Limitar","detalle":"Máximo diario y por ocasión.","icono":"Calculator","evidencia":"Plan."},{"titulo":"Verificar","detalle":"Uso y técnica en control.","icono":"ClipboardCheck","evidencia":"Seguimiento."}]},"caso":{"titulo":"Uso excesivo del mismo inhalador","contexto":"Paciente con MART que usa más de doce inhalaciones al día y no mejora.","pregunta":"¿Qué debe hacer?","opciones":[{"texto":"Esperar unos días.","correcta":false,"retro":"Debe consultar de inmediato."},{"texto":"Consultar por atención urgente.","correcta":true,"retro":"Supera el límite y no mejora."},{"texto":"Duplicar el mantenimiento.","correcta":false,"retro":"No es seguro sin valoración."}]}}$j$::jsonb;
