  -- 06. Asma en niños de 6 a 11 años: pasos de tratamiento, crisis y dispositivos
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La cámara que cambia el resultado","texto":"Un niño con asma recibe un inhalador sin cámara y la familia no sabe coordinar la inhalación. GINA 2026 insiste en dispositivos adecuados a la edad. En niños, la técnica y la educación familiar son tan importantes como la molécula."},"objetivos":["Aplicar los pasos de GINA en niños.","Reconocer la novedad del AIR en 2026.","Dosificar la prednisolona en crisis.","Elegir dispositivos adecuados."],"conceptos":[{"icono":"Wind","termino":"AIR","definicion":"Rescate antiinflamatorio con ICS-formoterol."},{"icono":"Pill","termino":"Prednisolona","definicion":"1-2 mg/kg/día, máximo 40 mg."},{"icono":"Gauge","termino":"PRAM","definicion":"Escala clínica validada en menores de 18 años."},{"icono":"Package","termino":"Cámara","definicion":"Facilita la inhalación en niños."}],"secciones":[{"titulo":"Pasos de tratamiento","parrafos":["En el paso 1 se usa AIR con ICS-formoterol a dosis baja a necesidad o ICS-SABA a dosis baja. En el paso 2, ICS diario a dosis baja más rescate; el montelukast es una alternativa menos eficaz. En el paso 3, ICS a dosis media, ICS-LABA a dosis baja o MART con ICS-formoterol a dosis baja. En el paso 4, ICS-LABA a dosis media, MART con el doble de la dosis del paso 3 o remisión; el tiotropio es una opción añadida.","La novedad de 2026 es incluir AIR con budesonida-formoterol en los pasos 1 y 2. En niños de 5 a 15 años, el rescate antiinflamatorio a dosis baja redujo casi a la mitad las exacerbaciones moderadas a graves frente al SABA solo."]},{"titulo":"Crisis y dispositivos","parrafos":["En exacerbaciones, la prednisolona se dosifica a 1-2 mg/kg/día, con un máximo de 40 mg, por 3-5 días. En menores de 18 años, GINA recomienda usar una escala clínica validada como PRAM para valorar la gravedad. La respuesta inicial y los signos de alarma determinan la conducta.","La técnica es crítica: los niños deben usar inhalador presurizado con cámara espaciadora. Cuando no hay cámara comercial, una botella plástica de 500 mL puede funcionar como alternativa. El dispositivo de polvo seco requiere flujo inspiratorio suficiente y no se recomienda en todos los niños."]},{"titulo":"Educación familiar","parrafos":["El QF enseña a la familia a reconocer síntomas, usar el plan de acción y administrar el rescate. También revisa la edad aprobada de cada presentación en el inserto INVIMA; por ejemplo, la ficha de referencia de budesonida-formoterol 160/4,5 no recomienda MART en menores de 12 años.","La adherencia en niños depende del cuidador. Involucrar a la escuela, revisar la técnica en cada consulta y simplificar el esquema mejora los resultados. La educación debe adaptarse a la edad y al nivel de comprensión."]}],"errores":[{"error":"Usar polvo seco sin verificar flujo.","correccion":"No todos los niños pueden."},{"error":"No involucrar al cuidador.","correccion":"La adherencia depende de él."},{"error":"Ignorar la edad del inserto.","correccion":"La indicación aprobada prevalece."}],"comprueba":[{"pregunta":"¿Dosis de prednisolona en crisis?","respuesta":"1-2 mg/kg/día, máximo 40 mg."},{"pregunta":"¿Qué escala se usa en niños?","respuesta":"PRAM."},{"pregunta":"¿Qué novedad trae GINA 2026?","respuesta":"AIR con ICS-formoterol en pasos 1 y 2."}],"resumen":["El asma pediátrica tiene pasos propios.","El AIR con ICS-formoterol llega a los pasos 1-2.","La prednisolona se dosifica por peso.","La técnica y la familia son determinantes."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Ministerio de Salud y Protección Social. Guía de práctica clínica para el diagnóstico y seguimiento de niños con asma (Guía n.º 01). Bogotá; 2013.","url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/INEC/IETS/GPC_Comp_Asma.pdf"}],"imagenes":[{"ubicacion":"Asma pediátrica","descripcion":"Niño usando inhalador con cámara espaciadora.","alt":"Asma en niños de 6 a 11 años"}],"keywords":["asma niños","gina 2026 pediatría","prednisolona asma","cámara espaciadora","pram"],"mapa":{"centro":"Asma pediátrica","ramas":[{"titulo":"Pasos","icono":"Route","nodos":["Paso 1","Paso 2","Paso 3","Paso 4"]},{"titulo":"Crisis","icono":"AlertTriangle","nodos":["Prednisolona","PRAM","Urgencia"]},{"titulo":"Dispositivos","icono":"Package","nodos":["pMDI","Cámara","Polvo seco"]},{"titulo":"Familia","icono":"Users","nodos":["Técnica","Adherencia","Plan"]}]},"proceso":{"titulo":"Abordaje pediátrico","intro":"","pasos":[{"titulo":"Clasificar","detalle":"Edad, síntomas y paso.","icono":"Gauge","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"Fármaco y dispositivo.","icono":"Package","evidencia":"Fórmula."},{"titulo":"Enseñar","detalle":"Técnica al cuidador.","icono":"GraduationCap","evidencia":"Demostración."},{"titulo":"Crisis","detalle":"Prednisolona y PRAM.","icono":"AlertTriangle","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Control y adherencia.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"Niño sin cámara","contexto":"Niño de 7 años con asma que usa inhalador presurizado sin cámara y presenta crisis frecuentes.","pregunta":"¿Qué prioriza el QF?","opciones":[{"texto":"Cambiar a otro corticoide.","correcta":false,"retro":"El problema puede ser la técnica."},{"texto":"Enseñar la técnica con cámara espaciadora.","correcta":true,"retro":"Mejora la deposición y el control."},{"texto":"Suspender el rescate.","correcta":false,"retro":"Necesita alivio seguro."}]}}$j$::jsonb;
