  -- 07. Asma de difícil control vs asma grave: evaluación y opciones del paso 5
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Antes de llamarla grave","texto":"Una paciente con tres ciclos de prednisolona al año parece tener asma grave. Al revisar, tiene 55 % de adherencia y dos errores críticos de técnica. Corregirlos puede cambiar el diagnóstico y evitar tratamientos costosos."},"objetivos":["Diferenciar difícil control y asma grave.","Identificar factores modificables.","Aplicar las opciones del paso 5.","Reconocer el lugar de la triple terapia."],"conceptos":[{"icono":"Search","termino":"Difícil control","definicion":"No controlada pese a tratamiento, con causas corregibles."},{"icono":"ShieldCheck","termino":"Asma grave","definicion":"Persiste tras corregir factores y optimizar."},{"icono":"Layers","termino":"Triple terapia","definicion":"ICS-LABA-LAMA; menos potente que biológicos."},{"icono":"Users","termino":"Adherencia","definicion":"Causa frecuente de aparente gravedad."}],"secciones":[{"titulo":"Difícil control frente a grave","parrafos":["El asma de difícil control es la que sigue sin controlarse a pesar de ICS-LABA a dosis media o alta, o la que necesita esas dosis para mantenerse controlada. Muchas veces la causa es modificable: técnica incorrecta, baja adherencia, tabaquismo, exposición laboral o doméstica, comorbilidades o un diagnóstico equivocado.","El asma grave es la que persiste no controlada aunque se hayan corregido estos factores con tratamiento óptimo. La distinción evita etiquetar como grave a quien solo necesita educación y adherencia."]},{"titulo":"Evaluación del paso 5","parrafos":["GINA 2026 recomienda remitir en el paso 5 para valoración experta y fenotipo: eosinófilos en sangre, FeNO, IgE y sensibilización alérgica. Antes de los biológicos se puede añadir un LAMA, como el tiotropio, o probar ICS-formoterol a dosis alta.","La triple terapia reduce las exacerbaciones graves menos que los biológicos, pero puede ayudar a quien no califica para ellos. El corticoide oral de mantenimiento es el último recurso por sus efectos adversos acumulados."]},{"titulo":"Optimizar antes de escalar","parrafos":["Un estudio de 2026 en asma grave mostró que el tratamiento inhalado de base influye en la posibilidad de lograr remisión con biológicos. Optimizar la terapia inhalada sigue siendo necesario aun cuando se inicia un biológico.","El QF revisa los registros de dispensación, la técnica y las barreras de acceso, y comunica al especialista un resumen estructurado. Documentar la intervención permite reevaluar la gravedad con datos objetivos."]}],"errores":[{"error":"Etiquetar grave sin revisar adherencia.","correccion":"Es la causa más frecuente."},{"error":"No revisar comorbilidades.","correccion":"Rinosinusitis y obesidad afectan."},{"error":"Usar corticoide oral crónico.","correccion":"Último recurso por toxicidad."}],"comprueba":[{"pregunta":"¿Qué es asma grave?","respuesta":"Persiste tras corregir factores y optimizar."},{"pregunta":"¿Qué opciones hay antes de biológicos?","respuesta":"LAMA o ICS-formoterol a dosis alta."},{"pregunta":"¿Qué biomarcadores se usan?","respuesta":"Eosinófilos, FeNO e IgE."}],"resumen":["Difícil control no es lo mismo que grave.","La técnica y la adherencia se revisan primero.","El paso 5 exige fenotipo y remisión.","La triple terapia no reemplaza a los biológicos."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Paso 5","descripcion":"Árbol de decisión entre difícil control y asma grave.","alt":"Asma de difícil control y asma grave"}],"keywords":["asma grave","asma difícil control","paso 5 asma","triple terapia asma"],"mapa":{"centro":"Paso 5","ramas":[{"titulo":"Revisar","icono":"Eye","nodos":["Técnica","Adherencia","Diagnóstico"]},{"titulo":"Comorbilidad","icono":"Network","nodos":["Rinosinusitis","Obesidad","Reflujo"]},{"titulo":"Opciones","icono":"Pill","nodos":["LAMA","Dosis alta","Biológicos"]},{"titulo":"Fenotipo","icono":"TestTube","nodos":["Eosinófilos","FeNO","IgE"]}]},"proceso":{"titulo":"Evaluación de gravedad","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Diagnóstico y fenotipo.","icono":"Search","evidencia":"Historia."},{"titulo":"Revisar","detalle":"Técnica y adherencia.","icono":"Eye","evidencia":"Registros."},{"titulo":"Corregir","detalle":"Exposiciones y comorbilidades.","icono":"Settings","evidencia":"Plan."},{"titulo":"Optimizar","detalle":"Dosis y combinación.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Remitir","detalle":"Fenotipo y biológicos.","icono":"FileCheck","evidencia":"Remisión."}]},"caso":{"titulo":"Tres ciclos de prednisolona","contexto":"Paciente de 50 años en Bucaramanga con ICS-LABA de dosis alta y tres ciclos de prednisolona en el año; adherencia de 55 % y dos errores críticos de técnica.","pregunta":"¿Cómo se clasifica por ahora?","opciones":[{"texto":"Asma grave definitiva.","correcta":false,"retro":"Faltan corregir factores modificables."},{"texto":"Asma de difícil control; reevaluar.","correcta":true,"retro":"Primero se corrige técnica y adherencia."},{"texto":"No tiene asma.","correcta":false,"retro":"El diagnóstico no está en duda."}]}}$j$::jsonb;
