  -- 08. Biológicos en asma grave: anti-IgE, anti-IL-5, anti-IL-4Rα y anti-TSLP
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El fenotipo decide el biológico","texto":"Dos pacientes con asma grave reciben biológicos distintos. Uno tiene IgE alta y sensibilización; el otro, eosinófilos altos y FeNO elevado. La diana y el fenotipo guían la elección. El QF participa en la gestión segura de estos medicamentos."},"objetivos":["Comparar los biológicos por diana.","Reconocer edad mínima y fenotipo.","Aplicar las tareas del QF en su gestión.","Reportar reacciones adversas."],"conceptos":[{"icono":"ShieldCheck","termino":"Anti-IgE","definicion":"Omalizumab; asma alérgica."},{"icono":"Target","termino":"Anti-IL-5","definicion":"Mepolizumab y benralizumab; eosinofílica."},{"icono":"Network","termino":"Anti-IL-4Rα","definicion":"Dupilumab; inflamación tipo 2."},{"icono":"Wind","termino":"Anti-TSLP","definicion":"Tezepelumab; amplio espectro."}],"secciones":[{"titulo":"Dianas y fenotipos","parrafos":["El omalizumab es un anti-IgE indicado en asma alérgica con sensibilización e IgE en rango, desde los 6 años. El mepolizumab y el benralizumab son anti-IL-5 o anti-receptor de IL-5, indicados en asma eosinofílica desde los 6 años. El dupilumab bloquea el receptor de IL-4α y se usa en inflamación tipo 2 desde los 6 años. El tezepelumab bloquea la linfopoyetina estromal tímica y tiene un espectro amplio, desde los 12 años.","La elección depende del fenotipo, la edad, las exacerbaciones, la dosis de ICS y las comorbilidades. Los biológicos no sustituyen la terapia inhalada óptima: se añaden a ella."]},{"titulo":"Gestión por el QF","parrafos":["El QF verifica indicación, dosis, peso e IgE cuando aplica, cadena de frío, técnica de administración y adherencia. También revisa la respuesta con exacerbaciones, control, dosis de corticoide oral y efectos adversos.","Las reacciones en el sitio de inyección y las reacciones de hipersensibilidad son los eventos más frecuentes. Cualquier sospecha se documenta y se reporta al Programa Nacional de Farmacovigilancia del INVIMA."]},{"titulo":"Seguimiento y expectativas","parrafos":["La respuesta suele evaluarse a los 4-6 meses con criterios definidos: menos exacerbaciones, mejor control, reducción de corticoide oral y mejor calidad de vida. Si no hay respuesta, se revisa el fenotipo y la adherencia antes de cambiar.","En Colombia, el acceso a biológicos es limitado y requiere justificación clínica. El QF puede apoyar la documentación y la continuidad del tratamiento. La educación del paciente sobre el objetivo y las expectativas mejora la adherencia."]}],"errores":[{"error":"Elegir sin fenotipo.","correccion":"La diana depende del perfil."},{"error":"Suspender la terapia inhalada.","correccion":"Los biológicos se añaden."},{"error":"No reportar reacciones.","correccion":"La farmacovigilancia es obligatoria."}],"comprueba":[{"pregunta":"¿Qué biológico es anti-IgE?","respuesta":"Omalizumab."},{"pregunta":"¿Cuál tiene espectro amplio?","respuesta":"Tezepelumab."},{"pregunta":"¿Qué se evalúa a los 4-6 meses?","respuesta":"Exacerbaciones, control y corticoide oral."}],"resumen":["El fenotipo guía la elección del biológico.","Los biológicos se añaden al tratamiento inhalado.","El QF gestiona acceso, administración y seguimiento.","Las reacciones se reportan al INVIMA."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Biológicos","descripcion":"Dianas de los biológicos y fenotipos correspondientes.","alt":"Biológicos en asma grave"}],"keywords":["biológicos asma","omalizumab","mepolizumab","dupilumab","tezepelumab"],"mapa":{"centro":"Biológicos","ramas":[{"titulo":"Anti-IgE","icono":"ShieldCheck","nodos":["Omalizumab","Alergia","IgE"]},{"titulo":"Anti-IL-5","icono":"Target","nodos":["Mepolizumab","Benralizumab","Eosinófilos"]},{"titulo":"Anti-IL-4R","icono":"Network","nodos":["Dupilumab","Tipo 2","FeNO"]},{"titulo":"Anti-TSLP","icono":"Wind","nodos":["Tezepelumab","Amplio","Sin fenotipo"]}]},"proceso":{"titulo":"Checklist de biológicos","intro":"","pasos":[{"titulo":"Fenotipo","detalle":"IgE, eosinófilos o FeNO.","icono":"TestTube","evidencia":"Resultados."},{"titulo":"Indicación","detalle":"Edad y criterios.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Gestión","detalle":"Cadena de frío y dosis.","icono":"Package","evidencia":"Registro."},{"titulo":"Administrar","detalle":"Técnica y vigilancia.","icono":"Syringe","evidencia":"Nota."},{"titulo":"Evaluar","detalle":"Respuesta y reporte.","icono":"LineChart","evidencia":"Seguimiento."}]},"caso":{"titulo":"Asma alérgica grave","contexto":"Paciente de 15 años con asma grave, IgE alta, sensibilización a ácaros y exacerbaciones frecuentes pese a ICS-LABA.","pregunta":"¿Qué biológico es candidato?","opciones":[{"texto":"Omalizumab.","correcta":true,"retro":"Anti-IgE para asma alérgica."},{"texto":"Tezepelumab en menores de 12.","correcta":false,"retro":"Su indicación inicia a los 12 años."},{"texto":"Ninguno; solo aumentar ICS.","correcta":false,"retro":"Ya está optimizado."}]}}$j$::jsonb;
