  -- 09. Caso: asma no controlada en el paso 4 con MART
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"El paso 4 que no funciona","texto":"Una paciente en paso 4 con MART sigue con exacerbaciones. Antes de pasar a biológicos hay que revisar técnica, adherencia, exposición y comorbilidades. El caso integra el tratamiento escalonado, la educación y la derivación."},"objetivos":["Aplicar el análisis del paso 4.","Revisar factores modificables.","Decidir entre optimizar y remitir.","Documentar el plan y el seguimiento."],"conceptos":[{"icono":"Route","termino":"Paso 4","definicion":"MART a dosis media o ICS-LABA media."},{"icono":"Eye","termino":"Técnica","definicion":"Errores críticos frecuentes."},{"icono":"TestTube","termino":"Fenotipo","definicion":"Eosinófilos, FeNO e IgE."},{"icono":"FileCheck","termino":"Remisión","definicion":"Valoración experta del paso 5."}],"secciones":[{"titulo":"Evaluación","parrafos":["Se confirma el diagnóstico y el paso actual, se revisa la técnica con demostración y se mide la adherencia con registros de dispensación. Se buscan exposiciones, tabaquismo, rinitis, reflujo, obesidad y apnea. También se revisan exacerbaciones, corticoide oral y uso de rescate.","Si la paciente usa MART, se verifica que entienda las dos funciones y los límites diarios. Un error frecuente es usar solo el rescate y omitir el mantenimiento."]},{"titulo":"Decisión","parrafos":["Si hay factores corregibles, se interviene antes de escalar: educación, técnica, tratamiento de la rinitis, control del reflujo y apoyo para el acceso. Si a pesar de la optimización persiste no controlada, se remite al paso 5 para fenotipo y valoración de biológicos.","El QF documenta la intervención con datos objetivos y envía un resumen al especialista. La decisión compartida con el paciente mejora la adherencia."]},{"titulo":"Seguimiento","parrafos":["Se agenda control en cuatro a ocho semanas con ACT, uso de rescate, exacerbaciones y técnica. Se refuerza el plan de acción y se revisan efectos adversos. Si se inicia un biológico, se mantiene la terapia inhalada y se evalúa la respuesta a los 4-6 meses.","El caso muestra que el paso 4 no siempre significa escalar: muchas veces significa ordenar. La revisión sistemática evita tratamientos innecesarios y mejora el control."]}],"errores":[{"error":"Escalar sin revisar adherencia.","correccion":"Es la causa más frecuente."},{"error":"No documentar la intervención.","correccion":"Sin datos no se reevalúa."},{"error":"No tratar comorbilidades.","correccion":"Afectan el control."}],"comprueba":[{"pregunta":"¿Qué se revisa primero?","respuesta":"Técnica y adherencia."},{"pregunta":"¿Cuándo remitir?","respuesta":"Si persiste sin control tras optimizar."},{"pregunta":"¿Qué se evalúa con el biológico?","respuesta":"Respuesta a los 4-6 meses."}],"resumen":["El paso 4 exige ordenar antes de escalar.","La técnica y la adherencia explican muchos fracasos.","Las comorbilidades modifican el control.","La remisión documentada abre el paso 5."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Ficha de paciente con MART, técnica y adherencia.","alt":"Caso de asma no controlada en paso 4"}],"keywords":["caso asma paso 4","mart no controlada","adherencia asma","biológicos asma"],"mapa":{"centro":"Paso 4","ramas":[{"titulo":"Control","icono":"ClipboardList","nodos":["Síntomas","Exacerbaciones","ACT"]},{"titulo":"Barreras","icono":"AlertTriangle","nodos":["Técnica","Adherencia","Costo"]},{"titulo":"Comorbilidad","icono":"Network","nodos":["Rinitis","Reflujo","Obesidad"]},{"titulo":"Decisión","icono":"Route","nodos":["Optimizar","LAMA","Biológico"]}]},"proceso":{"titulo":"Análisis del paso 4","intro":"","pasos":[{"titulo":"Confirmar","detalle":"Diagnóstico y paso.","icono":"Search","evidencia":"Historia."},{"titulo":"Medir","detalle":"Adherencia y técnica.","icono":"Eye","evidencia":"Registros."},{"titulo":"Buscar","detalle":"Exposiciones y comorbilidad.","icono":"Network","evidencia":"Entrevista."},{"titulo":"Optimizar","detalle":"Educación y acceso.","icono":"GraduationCap","evidencia":"Plan."},{"titulo":"Remitir","detalle":"Si persiste, paso 5.","icono":"FileCheck","evidencia":"Remisión."}]},"caso":{"titulo":"MART sin control","contexto":"Paciente en paso 4 con MART a dosis media, tres exacerbaciones en el año, técnica incorrecta y 60 % de adherencia.","pregunta":"¿Cuál es el siguiente paso?","opciones":[{"texto":"Iniciar biológico de inmediato.","correcta":false,"retro":"Primero se corrigen técnica y adherencia."},{"texto":"Optimizar técnica y adherencia; reevaluar.","correcta":true,"retro":"Puede cambiar el diagnóstico de gravedad."},{"texto":"Suspender el MART.","correcta":false,"retro":"Empeoraría el control."}]}}$j$::jsonb;
